import { BEFORE_HYDRATION_SCRIPT_ID } from "../../vite-plugin-scripts/const.js";
export { BEFORE_HYDRATION_SCRIPT_ID };
/**
* Serves `astro:scripts/before-hydration.js`, the `before-hydration` scripts, which run in the
* browser before the first island hydrates.
*/
export default function astroScriptsPlugin({ scripts }) {
	let command;
	return {
		name: "astro:scripts:before-hydration",
		config(_, env) {
			command = env.command;
		},
		resolveId: {
			filter: { id: new RegExp(`^${BEFORE_HYDRATION_SCRIPT_ID}$`) },
			handler(id) {
				return id;
			}
		},
		load: {
			filter: { id: new RegExp(`^${BEFORE_HYDRATION_SCRIPT_ID}$`) },
			handler() {
				return { code: scripts.filter((s) => s.stage === "before-hydration").map((s) => s.content).join("\n") };
			}
		},
		buildStart() {
			if (command === "serve") return;
			const hasHydrationScripts = scripts.some((s) => s.stage === "before-hydration");
			if (hasHydrationScripts && (this.environment.config.consumer === "client" || this.environment.config.consumer === "server")) {
				this.emitFile({
					type: "chunk",
					id: BEFORE_HYDRATION_SCRIPT_ID,
					name: BEFORE_HYDRATION_SCRIPT_ID
				});
			}
		}
	};
}
